9	// ValidateAggregateParams is the one place the startup limits shared by the
10	// library entry points and the command line are stated. These tests pin both
11	// the accepted region (including the entry-shared boundary spellings the
12	// callers depend on) and the structured report for every rejected limit, in
13	// the order it has always surfaced.
14	func TestValidateAggregateParamsAccepts(t *testing.T) {
15		cases := []struct {
16			name                 string
17			window, slide, parts int64
18		}{
19			{"fixed window", 1000, 1000, 0},
20			{"sliding window", 1000, 600, 0},
21			{"non-dividing interval", 1000, 300, 0},
22			{"single partition", 1000, 1000, 1},
23			{"many partitions with sliding", 1000, 600, 7},
24			{"library zero partitions is single-watermark mode", 1000, 1000, 0},
25		}
26		for _, tc := range cases {
27			t.Run(tc.name, func(t *testing.T) {
28				if err := ValidateAggregateParams(tc.window, tc.slide, tc.parts); err != nil {
29					t.Fatalf("ValidateAggregateParams(%d,%d,%d) = %v, want nil", tc.window, tc.slide, tc.parts, err)
30				}
31			})
32		}
33	}
34	
35	func TestValidateAggregateParamsRejects(t *testing.T) {
36		cases := []struct {
37			name                 string
38			window, slide, parts int64
39			field                AggregateParamName
40			kind                 AggregateParamKind
41			value, limit         int64
42			wantInError          string
43		}{
44			{"zero window", 0, 0, 0, AggregateParamWindow, AggregateParamNotPositive, 0, 0, "window length"},
45			{"negative window", -1, -1, 0, AggregateParamWindow, AggregateParamNotPositive, -1, 0, "window length"},
46			{"min window", -1 << 63, 0, 0, AggregateParamWindow, AggregateParamNotPositive, -1 << 63, 0, "window length"},
47			{"zero slide", 1000, 0, 0, AggregateParamSlide, AggregateParamNotPositive, 0, 0, "slide interval"},
48			{"negative slide", 1000, -600, 0, AggregateParamSlide, AggregateParamNotPositive, -600, 0, "slide interval"},
49			{"slide one over window", 1000, 1001, 0, AggregateParamSlide, AggregateParamTooLarge, 1001, 1000, "must not exceed"},
50			{"negative partitions", 1000, 1000, -1, AggregateParamPartitions, AggregateParamNotPositive, -1, 0, "partition count"},
51			{"min partitions", 1000, 600, -1 << 63, AggregateParamPartitions, AggregateParamNotPositive, -1 << 63, 0, "partition count"},
52		}
53		for _, tc := range cases {
54			t.Run(tc.name, func(t *testing.T) {
55				err := ValidateAggregateParams(tc.window, tc.slide, tc.parts)
56				if err == nil {
57					t.Fatal("expected error, got nil")
58				}
59				var pe *AggregateParamError
60				if !errors.As(err, &pe) {
61					t.Fatalf("error = %T, want *AggregateParamError: %v", err, err)
62				}
63				if pe.Field != tc.field || pe.Kind != tc.kind || pe.Value != tc.value || pe.Limit != tc.limit {
